bool isNumeric(const string& str) {
    istringstream iss(str);
    double test;
    iss >> noskipws >> test;
    return iss.eof() && !iss.fail();
}

bool isNumeric(char ch) {
    return isdigit(ch) != 0;
}

bool isLoggedIn = false;

bool validPassword(const string& password) {
    if (password.length() < 8) {
        return false; // Password length is less than 8 characters
    }

    bool hasNumber = false;
    bool hasCharacter = false;

    for (char c : password) {
        if (isdigit(c)) {
            hasNumber = true;
        }
        else if (isalpha(c)) {
            hasCharacter = true;
        }
    }

    return hasNumber && hasCharacter;
}

string getPasswordInput() {
    string password;
    char ch;

    while (true) {
        ch = _getch();
        if (ch == 13) // Enter key
            break;
        if (ch == 8) { // Backspace
            if (!password.empty()) {
                cout << "\b \b"; // Erase the character and move cursor back
                password.pop_back(); // Remove the last character from the password
            }
        }
        else {
            cout << '*';
            password += ch;
        }
    }
    cout << endl;

    return password;
}

bool isValidPhone(const string& phone) {// Define a regular expression for Malaysian phone number validation
    const regex phoneRegex("^(01[0-9]|011|012|013|014|015|016|017|018|019)[0-9]{7,8}$");
    return regex_match(phone, phoneRegex);
}

bool isValidDate(const std::string& dateStr) {
    std::tm tm = {};
    std::istringstream ss(dateStr);
    ss >> std::get_time(&tm, "%Y/%m/%d");
    return ss.eof() && !ss.fail();
}

bool isValidTime(const string& time) {
    // Define the regular expression for the "HH:MM" 24-hour format
    regex timeFormat("^([01]?[0-9]|2[0-3]):([0-5][0-9])$");

    // Check if the time matches the regular expression
    if (!regex_match(time, timeFormat)) {
        return false;
    }

    return true; // Time is valid
}

int convertToHours(string time) {
    int hours, minutes;
    char colon;

    stringstream ss(time);
    ss >> hours >> colon >> minutes;

    return hours * 60 + minutes;
}

int calculateRentalDuration(string Timepickup, string Timereturn) {
    int pickupTime = convertToHours(Timepickup);
    int returnTime = convertToHours(Timereturn);

    return returnTime - pickupTime; // Return duration in hours
}

bool isValidDatebooking(const string& date) {
    // Define the regular expression for the "YYYY-MM-DD" format
    regex dateFormat("^(\\d{4})/(0[1-9]|1[0-2])/(0[1-9]|[12][0-9]|3[01])$");

    // Check if the date matches the regular expression
    if (!regex_match(date, dateFormat)) {
        return false;
    }

    // Split the date into year, month, and day
    int year = stoi(date.substr(0, 4));
    int month = stoi(date.substr(5, 2));
    int day = stoi(date.substr(8, 2));

    // Get the current date
    time_t currentTime;
    struct tm currentTimeInfo;
    time(&currentTime);
    localtime_s(&currentTimeInfo, &currentTime);
    int currentYear = currentTimeInfo.tm_year + 1900;
    int currentMonth = currentTimeInfo.tm_mon + 1;
    int currentDay = currentTimeInfo.tm_mday;

    // Compare the date components with the current date
    if (year > currentYear ||
        (year == currentYear && month > currentMonth) ||
        (year == currentYear && month == currentMonth && day >= currentDay)) {
        return true; // Date is valid and greater than the current date
    }

    return false; // Date is not valid or is not greater than the current date
}
bool isValidDatecar(const string& date) {
    // Define the regular expression for the "YYYY-MM-DD" format
    regex dateFormat("^(\\d{4})/(0[1-9]|1[0-2])/(0[1-9]|[12][0-9]|3[01])$");

    // Check if the date matches the regular expression
    if (!regex_match(date, dateFormat)) {
        return false;
    }

    // Split the date into year, month, and day
    int year = stoi(date.substr(0, 4));
    int month = stoi(date.substr(5, 2));
    int day = stoi(date.substr(8, 2));

    // Get the current date
    time_t currentTime;
    struct tm currentTimeInfo;
    time(&currentTime);
    localtime_s(&currentTimeInfo, &currentTime);
    int currentYear = currentTimeInfo.tm_year + 1900;
    int currentMonth = currentTimeInfo.tm_mon + 1;
    int currentDay = currentTimeInfo.tm_mday;

    // Compare the date components with the current date
    if (year > currentYear ||
        (year == currentYear && month > currentMonth) ||
        (year == currentYear && month == currentMonth && day > currentDay)) {
        return true; // Date is valid and greater than the current date
    }

    return false; // Date is not valid or is not greater than the current date
}

string calculateMD5(const string& input) {
    HCRYPTPROV hProv = 0;
    HCRYPTHASH hHash = 0;
    BYTE hash[16];
    DWORD hashLen = 16;

    if (!CryptAcquireContext(&hProv, NULL, NULL, PROV_RSA_FULL, CRYPT_VERIFYCONTEXT)) {
        cerr << "CryptAcquireContext failed: " << GetLastError() << std::endl;
        return "";
    }

    if (!CryptCreateHash(hProv, CALG_MD5, 0, 0, &hHash)) {
        cerr << "CryptCreateHash failed: " << GetLastError() << std::endl;
        CryptReleaseContext(hProv, 0);
        return "";
    }

    if (!CryptHashData(hHash, (BYTE*)input.c_str(), input.length(), 0)) {
        cerr << "CryptHashData failed: " << GetLastError() << std::endl;
        CryptDestroyHash(hHash);
        CryptReleaseContext(hProv, 0);
        return "";
    }

    if (!CryptGetHashParam(hHash, HP_HASHVAL, hash, &hashLen, 0)) {
        cerr << "CryptGetHashParam failed: " << GetLastError() << std::endl;
        CryptDestroyHash(hHash);
        CryptReleaseContext(hProv, 0);
        return "";
    }

    string hashStr;
    for (DWORD i = 0; i < hashLen; i++) {
        char buf[3];
        sprintf_s(buf, "%02x", hash[i]);
        hashStr += buf;
    }

    CryptDestroyHash(hHash);
    CryptReleaseContext(hProv, 0);

    return hashStr;
}

void printCentered(const string& text) {
    CONSOLE_SCREEN_BUFFER_INFO csbi;
    int columns;

    // Get the number of columns in the console
    if (GetConsoleScreenBufferInfo(GetStdHandle(STD_OUTPUT_HANDLE), &csbi)) {
        columns = csbi.srWindow.Right - csbi.srWindow.Left + 1;
    }
    else {
        columns = 80; // Default width if getting console info fails
    }

    int padding = (columns - text.length()) / 2;
    if (padding > 0) {
        cout << string(padding, ' ') << text << endl;
    }
    else {
        cout << text << endl; // In case the text is longer than the console width
    }
}

