void adminlogin()
{
    string id, password;
    int attempts = 0;
    cout << "\n" << endl;
    cout << "***Login Page***" << endl;
    cout << "\n";

    while (true) {
        static int loop = 0;
        if (loop == 0)
            cin.ignore(1, '\n');

        // Basic validation for username (can be expanded based on requirements)
        do {
            cout << "Admin ID: ";
            getline(cin, id);

            if (id.empty()) {
                cout << "ID cannot be empty." << endl;
                continue;
            }
            else {
                break;
            }

        } while (true);

        do {
            cout << "Enter Password: ";
            password = getPasswordInput();

            if (password.empty())
            {
                cout << "Password Cannot be empty. Please try again.\n";
                attempts++;
                continue;
            }
            else {
                if (!validPassword(password)) {
                    cout << "Invalid Password. Please try again.\n";
                    attempts++;
                    continue;
                }
                else {
                    break;
                }
            }

        } while (attempts < 3);

        if (attempts == 3)
        {
            cout << "\x1b[37m";
            cout << "Maximum attempts reached. Please try again later.\n";
            cout << "\x1b[0m";
            system("pause");
            system("cls");
            main();
        }
        attempts = 0;
        break;
    }


    cout << endl;

    string hashedpwd = calculateMD5(password);
    string checkUser_query = "SELECT * FROM admin WHERE adminID = '" + id + "' AND adminPassword = '" + hashedpwd + "'";
    const char* cu = checkUser_query.c_str();

    qstate = mysql_query(conn, cu);

    if (!qstate) {
        res = mysql_store_result(conn);
        if (res != NULL && res->row_count == 1) {
            row = mysql_fetch_row(res);

            string adminaccess = row[6];
            if (adminaccess == "1") {
                currentAdminID = row[0];
                string adminName = row[1];
                currentAdminIDRole = row[5];

                cout << "Welcome, " << adminName << "!" << endl;

                isLoggedIn = true; // Set isLoggedIn to true upon successful login
                system("pause");
                system("Color 17");//Blue background, black text
                adminMenu(); // Redirect to admin menu after successful login


            }
            else {
                cout << "Your account is inactive. Please contact support." << endl;
                system("pause");
                admin();
            }
        }
        else {
            char c;
            cout << "Invalid username or password. Want to try again? (Y/N): ";
            cin >> c;
            if (c == 'Y' || c == 'y')
            {
                admin();
            }
            else
            {
                system("cls");
                main();
            }
        }
    }
    else {
        cout << "Query Execution Problem!" << mysql_errno(conn) << endl;

    }
}

