void managerentalcar()
{
    system("cls");
    if (!isLoggedIn) {
        cout << "Access denied. Please login first.\n\n";
        adminlogin();  // Redirect to login if not logged in
        return;
    }
    system("Color 17");//Blue background, black text
    string adminmanagerentalcar_choice;
    try {

        do {
            cout << endl;
            printCentered("**********   WELCOME TO UTeM Car Rental System   **********");
            printCentered("*                 Manage Rental Car Menu                  *");
            printCentered("***********************************************************");
            printCentered("* 1. Edit Car Detais                                      *");
            printCentered("* 2. View Car List                                        *");
            printCentered("* 3. Delete Car                                           *");
            printCentered("* 4. Back to Admin Menu                                   *");
            printCentered("***********************************************************");
            cout<< endl;
            cout << "-> ";
            cin >> adminmanagerentalcar_choice;

            if (!isNumeric(adminmanagerentalcar_choice)) {
                cout << "Invalid input. Please enter numbers only." << endl;
                cin.clear(); // Clear error flags
                while (cin.get() != '\n'); // Discard invalid input
                system("pause");
                system("cls");
                continue;
            }

            // Convert char to int
            int a_managerentalcaroption = stoi(adminmanagerentalcar_choice);

            if (a_managerentalcaroption < 1 || a_managerentalcaroption > 4) {
                cout << "Invalid option. Please enter a number between 1 and 4." << endl;
                system("pause");
                system("cls");
                continue;
            }

            switch (a_managerentalcaroption) {
            case 1:
                editcar();
                system("pause");
                system("cls");
                break;
            case 2:
                viewcar();
                system("pause");
                system("cls");
                break;
            case 3:
                deletecar();
                system("pause");
                system("cls");
                break;
            case 4:
                cout << "Are you sure you want to go back? (Y/N): ";
                char adminmanagerentalcarconfirmQuit;
                cin >> adminmanagerentalcarconfirmQuit;
                if (toupper(adminmanagerentalcarconfirmQuit) == 'Y') {
                    system("cls");
                    adminMenu();
                }
                else {
                    system("cls");
                }
                break;
            }
        } while (true); // Infinite loop until user chooses to quit
    }
    catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
    }
}
 
