void deletecar()
{
    system("cls");
    if (!isLoggedIn) {
        cout << "Access denied. Please login first.\n\n";
        adminlogin();  // Redirect to login if not logged in
        return;
    }
    system("Color 17");//Blue background, black text

    // Check for access
    string accessQuery = "SELECT * FROM admin WHERE adminID = '" + currentAdminID + "'";
    qstate = mysql_query(conn, accessQuery.c_str());

    if (qstate) {
        cout << "Error in executing query: " << mysql_error(conn) << endl;
        managerentalcar();
    }

    res = mysql_store_result(conn);
    if (res != nullptr) {
        row = mysql_fetch_row(res);
        string role = row[5];
        mysql_free_result(res);

        if (role != "Yes") {
            cout << endl << endl;
            cout << "\t\tAccess restricted to admin master only.\n";
            cout << endl;
            system("pause");
            managerentalcar();
        }
    }

    printCentered("*********************************************");
    printCentered("|                                           |");
    printCentered("|-------------------------------------------|");
    printCentered("|           Delete Car Details              |");
    printCentered("|-------------------------------------------|");
    printCentered("|                                           |");
    printCentered("*********************************************");
    cout << endl;


    string query = "SELECT * FROM rentalcar"; 
    qstate = mysql_query(conn, query.c_str());

    if (!qstate)
    {
        res = mysql_store_result(conn);
        if (res != nullptr && res->row_count > 0)
        {
            cout << endl;
            cout << "+------------+----------------------+-------------------------+----------------------+----------------+\n";
            cout << "| Car ID     | Brand                |      Year               |      Model           |       unit     |\n";
            cout << "+------------+----------------------+-------------------------+----------------------+----------------+\n";
            while (row = mysql_fetch_row(res)) {
                cout << "| " << setw(10) << left << string(row[0]) << " | "
                    << setw(20) << left << string(row[1]) << " | "
                    << setw(23) << left << string(row[2]) << " | "
                    << setw(20) << left << string(row[3]) << " | "
                    << setw(14) << left << string(row[4]) << " | \n";
            }
            cout << "+------------+----------------------+-------------------------+----------------------+----------------+\n";
        }
        else
        {
            cout << endl << endl;
            printCentered("******************************************************************************");
            printCentered("*                                                                            *");
            printCentered("*                               No Car Found                                 *");
            printCentered("*                                                                            *");
            printCentered("******************************************************************************");
            cout << endl;
            system("pause");
            system("cls");
            managerentalcar();
        }
    }
    else
    {
        cout << "Error in executing query: " << mysql_error(conn) << endl;
    }
    cout << endl;
    char goback;
    cout << endl << "Press [B] to go back, or Press [Y] to continue? (B/Y): ";
    cin >> goback;

    if (toupper(goback) == 'B')
    {
        managerentalcar();
        system("cls");
    }
    else if (toupper(goback) == 'Y')
    {
        string carid;
        cout << "Enter Car ID to view details: ";
        cin >> carid;

        string details_query = "SELECT * FROM rentalcar_details WHERE carID = '" + carid + "'";

        qstate = mysql_query(conn, details_query.c_str());

        if (!qstate)
        {
            res = mysql_store_result(conn);
            if (res != nullptr && res->row_count > 0)
            {
                cout << "\nDetails for Car ID: " << carid << endl;
                cout << "+----------------------+-----------------+--------------+-----------------+---------------+----------------+----------------+\n";
                cout << "| plate_num            | Type            | Transmission | Road-Tax        | Rate per Hour | Status         |   Car Owner ID |\n";
                cout << "+----------------------+-----------------+--------------+-----------------+---------------+----------------+----------------+\n";

                while (row = mysql_fetch_row(res)) {
                    cout << "| " << setw(20) << left << string(row[1]) << " | "
                        << setw(15) << left << string(row[2]) << " | "
                        << setw(12) << left << string(row[3]) << " | "
                        << setw(15) << left << string(row[4]) << " | "
                        << setw(13) << left << string(row[5]) << " | "
                        << setw(14) << left << string(row[6]) << " | "
                        << setw(13) << left << string(row[7]) << "  | \n";
                }
                cout << "+----------------------+-----------------+--------------+-----------------+---------------+----------------+----------------+\n";

            }
            else
            {
                cout << "No details found for Car ID: " << carid << endl;
                system("pause");
                system("cls");
                deletecar();
            }
            mysql_free_result(res);
        }
        else
        {
            cout << "Error in executing query: " << mysql_error(conn) << endl;
        }

        string carnum;
        cout << "\nEnter the plate number of the car you want to delete: ";
        cin >> carnum;

        string check_car_query = "SELECT * FROM rentalcar_details WHERE car_number = '" + carnum + "'";
        qstate = mysql_query(conn, check_car_query.c_str());
        if (qstate) {
            cout << "Error in executing the query: " << mysql_error(conn) << endl;
            system("pause");
            managerentalcar();
            
        }

        res = mysql_store_result(conn);
        if (res->row_count != 1) {
            cout << "Car with plate number '" << carnum << "' not found.\n";
            system("pause");
            deletecar();
        }

        char confirm;
        cout << "Are you sure you want to delete the car with plate number '" << carnum << "'? (y/n): ";
        cin >> confirm;

        if (confirm == 'y' || confirm == 'Y') {
            string delete_query = "DELETE FROM rentalcar_details WHERE car_number = '" + carnum + "'";
            qstate = mysql_query(conn, delete_query.c_str());
            if (qstate) {
                cout << "Error in executing the deletion query: " << mysql_error(conn) << endl;
                system("pause");
                managerentalcar();
            }

            cout << "Car with plate number '" << carnum << "' deleted successfully!" << endl;
            system("pause");
            deletecar();
        }
        else {
            cout << "Deletion canceled." << endl;
            system("pause");
            deletecar();
        }

    }
    else {
        deletecar();
    }

    cout << endl;
    system("pause");
    system("cls");
    managerentalcar();


}

void managestudent()
{
    system("cls");
    if (!isLoggedIn) {
        cout << "Access denied. Please login first.\n\n";
        adminlogin();  // Redirect to login if not logged in
        return;
    }
    system("Color 17");//Blue background, black text
    string adminmanagerentalcar_choice;
    try {

        do {
            cout << endl;
            printCentered("**********   WELCOME TO UTeM Car Rental System   **********");
            printCentered("*                  Manage Student Menu                    *");
            printCentered("***********************************************************");
            printCentered("* 1. Edit Student list                                    *");
            printCentered("* 2. View Student list                                    *");
            printCentered("* 3. Delete Student list                                  *");
            printCentered("* 4. Back to Admin Menu                                   *");
            printCentered("***********************************************************");
            cout<< endl;
            cout << "-> ";
            cin >> adminmanagerentalcar_choice;

            if (!isNumeric(adminmanagerentalcar_choice)) {
                cout << "Invalid input. Please enter numbers only." << endl;
                cin.clear(); // Clear error flags
                while (cin.get() != '\n'); // Discard invalid input
                system("pause");
                system("cls");
                continue;
            }

            // Convert char to int
            int a_managerentalcaroption = stoi(adminmanagerentalcar_choice);

            if (a_managerentalcaroption < 1 || a_managerentalcaroption > 4) {
                cout << "Invalid option. Please enter a number between 1 and 4." << endl;
                system("pause");
                system("cls");
                continue;
            }

            switch (a_managerentalcaroption) {
            case 1:
                editstudentlist();
                system("pause");
                system("cls");
                break;
            case 2:
                viewstudentlist();
                system("pause");
                system("cls");
                break;
            case 3:
                deletestudentlist();
                system("pause");
                system("cls");
                break;
            case 4:
                cout << "Are you sure you want to go back? (Y/N): ";
                char adminmanagerentalcarconfirmQuit;
                cin >> adminmanagerentalcarconfirmQuit;
                if (toupper(adminmanagerentalcarconfirmQuit) == 'Y') {
                    system("cls");
                    adminMenu();
                }
                else {
                    system("cls");
                }
                break;
            }
        } while (true); // Infinite loop until user chooses to quit
    }
    catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
    }

}

