void studentlogin()
{
    string matric, password;
    int attempts = 0;
    cout << "\n" << endl;
    cout << "***Student Login Page***" << endl;
    cout << "\n";

    while (true) {
        static int loop = 0;
        if (loop == 0)
            cin.ignore(1, '\n');

        // Basic validation for username (can be expanded based on requirements)
        do {
            cout << "Student Matric: ";
            getline(cin, matric);

            if (matric.empty()) {
                cout << "Matric cannot be empty." << endl;
                continue;
            }
            else {
                break;
            }

        } while (true);

        do {
            cout << "Enter Password: ";
            password = getPasswordInput();

            if (password.empty())
            {
                cout << "Password Cannot be empty. Please try again.\n";
                attempts++;
                continue;
            }
            else {
                if (!validPassword(password)) {
                    cout << "Invalid Password. Please try again.\n";
                    attempts++;
                    continue;
                }
                else {
                    break;
                }
            }

        } while (attempts < 3);

        if (attempts == 3)
        {
            cout << "\x1b[37m";
            cout << "Maximum attempts reached. Please try again later.\n";
            cout << "\x1b[0m";
            system("pause");
            system("cls");
            main();
        }
        attempts = 0;
        break;
    }


    cout << endl;
    string student_hashedpwd = calculateMD5(password);
    string checkUser_query = "SELECT * FROM student WHERE studentMatric = '" + matric + "' AND studentPassword = '" + student_hashedpwd + "'";
    const char* cu = checkUser_query.c_str();

    qstate = mysql_query(conn, cu);

    if (!qstate) {
        res = mysql_store_result(conn);
        if (res != NULL && res->row_count == 1) {
            row = mysql_fetch_row(res);
            string studentaccess = row[9];
            if (studentaccess == "1") {
                currentstudentID = row[0];
                string studentName = row[1];

                cout << "Welcome, " << studentName << "!" << endl;

                isLoggedIn = true; // Set isLoggedIn to true upon successful login
                system("pause");
                system("Color 0F");
                studentMenu(); // Redirect to admin menu after successful login


            }
            else {
                string adminnumberquery = "SELECT * FROM admin WHERE adminmaster='Yes' AND adminaccess='1'";
                const char* aq = adminnumberquery.c_str();
                qstate = mysql_query(conn, aq);
                if (!qstate)
                {
                    res = mysql_store_result(conn);
                    if (res != NULL)
                    {
                        cout << "+-------------------+-------------------+" << endl;
                        cout << "| Admin Name        | Admin Phone       |" << endl;
                        cout << "+-------------------+-------------------+" << endl;

                        while ((row = mysql_fetch_row(res)))
                        {
                            cout << "| " << setw(17) << left << row[1] << " | " << setw(17) << left << row[2] << " |" << endl;
                        }
                        cout << "+-------------------+-------------------+" << endl;

                    }
                }
                else {
                    cout << "Query Execution Problem! Error code:" << mysql_errno(conn) << endl;;
                }

                cout << "Your account is inactive. Please contact support." << endl;
                system("pause");
                student();
            }
        }
        else {
            char c;
            cout << "Invalid Matric number or password. Want to try again? (Y/N): ";
            cin >> c;
            if (c == 'Y' || c == 'y')
            {
                student();
            }
            else
            {
                system("cls");
                main();
            }
        }
    }
    else {
        cout << "Query Execution Problem!" << mysql_errno(conn) << endl;

    }

}

