void carownerlogin()
{
    string ic, password;
    int attempts = 0;
    cout << "\n" << endl;
    cout << "***Login Page***" << endl;
    cout << "\n";

    while (true) {
        static int loop = 0;
        if (loop == 0)
            cin.ignore(1, '\n');

        // Basic validation for username (can be expanded based on requirements)
        do
        {
            cout << "Enter IC Number (without '-'): ";
            getline(cin, ic);

            if (ic.empty())
            {
                cout << "IC cannot be empty. Please try again.\n";
            }
            else if (regex_match(ic, regex("^[A-Za-z]+$")))
            {
                cout << "IC cannot be Alphabets. Please try again.\n";
            }
            else {
                if (!regex_match(ic, regex("\\d{12}")))
                {
                    cout << "IC must be 12 Digits! (e.g. 010101020101). Please try again.\n";
                    continue;
                }
                else {
                    break;
                }
            }
        } while (true);

        do {
            cout << "Enter Password: ";
            password = getPasswordInput();

            if (password.empty())
            {
                cout << "Password Cannot be empty. Please try again.\n";
                attempts++;
                continue;
            }
            else {
                if (!validPassword(password)) {
                    cout << "Invalid Password. Please try again.\n";
                    attempts++;
                    continue;
                }
                else {
                    break;
                }
            }

        } while (attempts < 3);

        if (attempts == 3)
        {
            cout << "\x1b[37m";
            cout << "Maximum attempts reached. Please try again later.\n";
            cout << "\x1b[0m";
            system("pause");
            system("cls");
            main();
        }
        attempts = 0;
        break;
    }

    cout << endl;
    string owner_hashedpwd = calculateMD5(password);
    string checkUser_query = "SELECT * FROM carowner WHERE ownerIC = '" + ic + "' AND ownerPassword = '" + owner_hashedpwd + "'";
    const char* cu = checkUser_query.c_str();

    qstate = mysql_query(conn, cu);

    if (!qstate) {
        res = mysql_store_result(conn);
        if (res != NULL && res->row_count == 1) {

            row = mysql_fetch_row(res);
            string ownerStatus = row[8];
            string owneraccess = row[9];
            if (ownerStatus == "APPROVE" && owneraccess == "1") {
                currentcarownerID = row[0];
                string ownerName = row[1];

                cout << "Welcome, " << ownerName << "!" << endl;

                isLoggedIn = true; // Set isLoggedIn to true upon successful login
                system("pause");
                system("Color 0b"); // black background, Blue text
                carownerMenu(); // Redirect to admin menu after successful login


            }
            else if (ownerStatus == "PENDING") {
                string adminnumberquery = "SELECT * FROM admin WHERE adminmaster='Yes' AND adminaccess='1'";
                const char* aq = adminnumberquery.c_str();
                qstate = mysql_query(conn, aq);
                if (!qstate)
                {
                    res = mysql_store_result(conn);
                    if (res != NULL)
                    {
                        cout << "+-------------------+-------------------+" << endl;
                        cout << "| Admin Name        | Admin Phone       |" << endl;
                        cout << "+-------------------+-------------------+" << endl;

                        while ((row = mysql_fetch_row(res)))
                        {
                            cout << "| " << setw(17) << left << row[1] << " | " << setw(17) << left << row[2] << " |" << endl;
                        }
                        cout << "+-------------------+-------------------+" << endl;

                    }
                }
                else {
                    cout << "Query Execution Problem! Error code:" << mysql_errno(conn) << endl;;
                }
                cout << "Your account is still pending approval. Please wait until it is approved or Contact support." << endl;
                system("pause");
                carowner();
            }
            else {
                string adminnumberquery = "SELECT * FROM admin WHERE adminmaster='Yes' AND adminaccess='1'";
                const char* aq = adminnumberquery.c_str();
                qstate = mysql_query(conn, aq);
                if (!qstate)
                {
                    res = mysql_store_result(conn);
                    if (res != NULL)
                    {
                        cout << "+-------------------+-------------------+" << endl;
                        cout << "| Admin Name        | Admin Phone       |" << endl;
                        cout << "+-------------------+-------------------+" << endl;

                        while ((row = mysql_fetch_row(res)))
                        {
                            cout << "| " << setw(17) << left << row[1] << " | " << setw(17) << left << row[2] << " |" << endl;
                        }
                        cout << "+-------------------+-------------------+" << endl;

                    }
                }
                else {
                    cout << "Query Execution Problem! Error code:" << mysql_errno(conn) << endl;;
                }
                cout << "Your account is not approved or inactive. Please contact support." << endl;
                system("pause");
                carowner();
            }
        }
        else {
            char c;
            cout << "Invalid username or password. Want to try again? (Y/N): ";
            cin >> c;
            if (c == 'Y' || c == 'y')
            {
                carowner();
            }
            else
            {
                system("cls");
                main();
            }
        }
    }
    else {
        cout << "Query Execution Problem!" << mysql_errno(conn) << endl;

    }
}

