void coaddcar()
{
    system("cls");
    if (!isLoggedIn) {
        cout << "Access denied. Please login first.\n\n";
        carownerlogin();  // Redirect to login if not logged in
        return;
    }
    system("Color 0b");//Blue background, black text
    string carnum, car_brand, caryear, car_model, car_type, car_roadtax, car_transmission, car_rent_price;
    static int loop = 0;
    cout << endl;
    printCentered("*********************************************");
    printCentered("|                                           |");
    printCentered("|-------------------------------------------|");
    printCentered("|               Add New Car                 |");
    printCentered("|-------------------------------------------|");
    printCentered("|                                           |");
    printCentered("*********************************************");
    cout << endl;

    if (loop == 0)
        cin.ignore(1, '\n');

    do {
        cout << "Enter Car Number Plate (ABC1234): ";
        getline(cin, carnum);

        if (carnum.empty()) {
            cout << "ID number cannot be empty. Please try again.\n";
        }
        else if (regex_match(carnum, regex("^[0-9]+$")))
        {
            cout << "Number Plate cannot be number only. Please try again.\n";
        }
        else if (regex_match(carnum, regex("^[A-Za-z]+$")))
        {
            cout << "Number Plate cannot be letter only. Please try again.\n";
        }
        else {
            transform(carnum.begin(), carnum.end(), carnum.begin(), ::toupper);

            if (!regex_match(carnum, regex("^[A-Za-z0-9]+$"))) {
                cout << "ID number should contain letters and numbers. Please try again.\n";
            }
            else {
                break; // Valid ID entered, exit the loop
            }
        }
    } while (true);

    string checkcar_query = "select * from rentalcar_details where car_number = '" + carnum + "'";
    const char* cu = checkcar_query.c_str();
    qstate = mysql_query(conn, cu);

    if (!qstate)
    {
        res = mysql_store_result(conn);
        if (res->row_count == 1)
        {
            cout << "Car number plate is already exist. Do you want continue? (Y/N): ";
            char addadminconfirmquit;
            cin >> addadminconfirmquit;
            if (toupper(addadminconfirmquit) == 'Y')
            {
                system("cls");
                coaddcar();
            }
            else {
                system("cls");
                managerentalcar();
            }

        }
        else
        {
            do {
                cout << "Enter Brand Name: ";
                getline(cin, car_brand);

                if (car_brand.empty())
                {
                    cout << "Name cannot be empty. Please try again.\n";
                }
                else if (regex_match(car_brand, regex("^[0-9]+$")))
                {
                    cout << "Brand Name cannot be number. Please try again.\n";
                }
                else {
                    transform(car_brand.begin(), car_brand.end(), car_brand.begin(), ::toupper);

                    if (!regex_match(car_brand, regex("^[A-Za-z]+$"))) {
                        cout << "Invalid Last Name. Please enter a valid Brand name." << endl;
                    }
                    else {
                        break;
                    }
                }
            } while (true);

            do {
                cout << "Enter Model Name: ";
                getline(cin, car_model);

                if (car_model.empty())
                {
                    cout << "Model cannot be empty. Please try again.\n";
                }
                else if (regex_match(car_model, regex("^[0-9]+$")))
                {
                    cout << "Model Name cannot be number. Please try again.\n";
                }
                else {
                    transform(car_model.begin(), car_model.end(), car_model.begin(), ::toupper);

                    if (!regex_match(car_model, regex("^[A-Z0-9 ]+$"))) {
                        cout << "Invalid Last Name. Please enter a valid Model name." << endl;
                    }
                    else {
                        break;
                    }
                }
            } while (true);

            do {
                cout << "Enter Year of Manufacture: ";
                getline(cin, caryear);

                if (caryear.empty()) {
                    cout << "Year cannot be empty. Please try again.\n";
                }
                else {
                    try {
                        int year = stoi(caryear);
                        time_t currentTime;
                        struct tm currentTimeInfo;
                        time(&currentTime);
                        localtime_s(&currentTimeInfo, &currentTime);
                        int currentYear = currentTimeInfo.tm_year + 1900;
                        if (year < 1900 || year > currentYear) {
                            cout << "Invalid year. Please enter a year between 1900 and current year.\n";
                        }
                        else {
                            break;
                        }
                    }
                    catch (const invalid_argument& ia) {
                        cout << "Invalid input. Please enter a valid year.\n";
                    }
                }
            } while (true);

            do {
                cout << "Enter Car Road-Tax(YYYY/MM/DD): ";
                getline(cin, car_roadtax);

                if (car_roadtax.empty()) {
                    cout << "Road-Tax cannot be empty. Please try again.\n";
                }
                else if (regex_match(car_roadtax, regex("^[A-Za-z]+$")))
                {
                    cout << "Road-Tax cannot be letter. Please try again.\n";
                }
                else if (regex_match(car_roadtax, regex("^[0-9]+$")))
                {
                    cout << "Road-Tax cannot be number only. Please try again.\n";
                }
                else {
                    if (!isValidDatecar(car_roadtax))
                    {
                        cout << "Road-Tax expired. Please try again." << endl;
                    }
                    else {
                        break;
                    }
                }
            } while (true);



            do {
                cout << "Enter Car Type(SEDAN,SUV,CROSSOVER....Etc): ";
                getline(cin, car_type);

                if (car_type.empty())
                {
                    cout << "Model cannot be empty. Please try again.\n";
                }
                else if (regex_match(car_type, regex("^[0-9]+$")))
                {
                    cout << "Model Name cannot be number. Please try again.\n";
                }
                else {
                    transform(car_type.begin(), car_type.end(), car_type.begin(), ::toupper);

                    if (!regex_match(car_type, regex("^[A-Za-z]+$"))) {
                        cout << "Invalid Last Name. Please enter a valid car type." << endl;
                    }
                    else {
                        break;
                    }
                }
            } while (true);

            do {
                cout << "Enter Car Transmission (Auto/Manual): ";
                getline(cin, car_transmission);

                if (car_transmission.empty())
                {
                    cout << "Car Transmission cannot be empty. Please try again.\n";
                }
                else if (regex_match(car_transmission, regex("^[0-9]+$")))
                {
                    cout << "Car Transmission cannot be number. Please try again.\n";
                }
                else {
                    transform(car_transmission.begin(), car_transmission.end(), car_transmission.begin(), ::toupper);

                    if (!regex_match(car_transmission, regex("^(AUTO|MANUAL)$"))) {
                        cout << "Invalid input. Please enter 'Auto' or 'Manual' only.\n";
                    }
                    else {
                        break;
                    }
                }
            } while (true);


            do
            {
                cout << "Enter rent per hour:RM ";
                getline(cin, car_rent_price);

                if (car_rent_price.empty())
                {
                    cout << "Rental price cannot be empty. Please try again.\n";
                }
                else if (regex_match(car_rent_price, regex("^[A-Za-z]+$")))
                {
                    cout << "Rental price cannot be letter. Please try again.\n";
                }
                else {
                    if (!regex_match(car_rent_price, regex("^[0-9]+(\\.[0-9]{1,2})?$")))
                    {
                        cout << "Invalid Rental Price. Please enter a valid numeric value.\n";
                    }
                    else {
                        break;
                    }
                }

            } while (true);

            // Check if similar model and year exist
            string query = "SELECT carID FROM rentalcar WHERE car_brand = '" + car_brand + "' AND car_year = '" + caryear + "' AND car_model = '" + car_model + "'";

            if (mysql_query(conn, query.c_str()) != 0) {
                cout << "Error in checking existing rentalcar record: " << mysql_error(conn) << endl;
                system("pause");
                cardetails();
            }

            MYSQL_RES* result = mysql_store_result(conn);
            if (result == nullptr) {
                cout << "Error in retrieving result: " << mysql_error(conn) << endl;
                system("pause");
                cardetails();
            }

            int carID;
            if (mysql_num_rows(result) > 0) {
                MYSQL_ROW row = mysql_fetch_row(result);
                carID = atoi(row[0]);
            }
            else {

                string insert_master_query = "INSERT INTO rentalcar (car_brand, car_year, car_model) VALUES ('" + car_brand + "', '" + caryear + "', '" + car_model + "')";
                if (mysql_query(conn, insert_master_query.c_str()) != 0) {
                    cout << "Error in inserting rentalcar record: " << mysql_error(conn) << endl;
                    mysql_free_result(result);
                    system("pause");
                    cardetails();
                }

                mysql_query(conn, "SELECT LAST_INSERT_ID()");
                result = mysql_store_result(conn);
                if (result == nullptr) {
                    cout << "Error in retrieving result: " << mysql_error(conn) << endl;
                    system("pause");
                    cardetails();
                }
                MYSQL_ROW row = mysql_fetch_row(result);
                carID = atoi(row[0]); 
            }
            mysql_free_result(result);

            query = "INSERT INTO rentalcar_details (carID,car_number,car_type,car_transmission,car_roadtax,car_rateper_hour,car_status,ownerID) VALUES (" + to_string(carID) + ", '" + carnum + "', '" + car_type + "', '" + car_transmission + "','" + car_roadtax + "', '" + car_rent_price + "','AVAILABLE','"+currentcarownerID+"')";
            if (mysql_query(conn, query.c_str()) != 0) {
                cout << "Error in inserting rentalcar_details record: " << mysql_error(conn) << endl;
                system("pause");
                cardetails();
            }
            cout << endl;
            cout << "Car added successfully!" << endl;

        }
    }
    else {
        cout << "Query Execution Problem!" << mysql_errno(conn) << endl;
        _getch();
        cardetails();
    }
    cout << endl;
    system("pause");
    cardetails();

}

